import { createHash } from "node:crypto";
export const identifier = (name) => `"${name.replaceAll('"', '""')}"`;
// Caller owns a repeatable-read transaction. JSON text is generated by PG in
// UTC, retaining microseconds and bytea; Node never parses guest row contents.
export async function snapshotTables(client) {
  const catalog = (
    await client.query(
      "SELECT tablename AS name FROM pg_tables WHERE schemaname='public' ORDER BY tablename",
    )
  ).rows;
  const tables = [];
  for (const { name } of catalog) {
    const hash = createHash("sha256");
    let rows = 0;
    const wide =
      (
        await client.query(
          "SELECT 1 FROM information_schema.columns WHERE table_schema='public' AND table_name=$1 AND data_type IN ('bytea','json','jsonb') LIMIT 1",
          [name],
        )
      ).rowCount > 0;
    await client.query(
      `DECLARE backup_rows NO SCROLL CURSOR FOR SELECT to_jsonb(t)::text AS row FROM public.${identifier(name)} t ORDER BY to_jsonb(t)::text`,
    );
    try {
      for (;;) {
        const batch = await client.query(
          `FETCH FORWARD ${wide ? 1 : 64} FROM backup_rows`,
        );
        if (batch.rows.length === 0) break;
        for (const value of batch.rows) {
          hash.update(value.row).update("\n");
          rows++;
        }
      }
    } finally {
      await client.query("CLOSE backup_rows");
    }
    tables.push({ name, rows, sha256: hash.digest("hex") });
  }
  return tables;
}
export async function migrationSnapshot(client) {
  return (
    await client.query(
      'SELECT migration_name AS name, checksum AS sha256 FROM "_prisma_migrations" WHERE finished_at IS NOT NULL AND rolled_back_at IS NULL ORDER BY migration_name',
    )
  ).rows;
}
